using System.Text.Json;
using System.Text.Json.Serialization;
using Htt.Infrastructure;
using Htt.Host.Api.MasterData;
using Htt.SharedKernel;
using NpgsqlTypes;
using static Htt.Host.Api.MasterData.MasterDataSupport;
using static Htt.Host.Api.Sales.SalesSupport;
namespace Htt.Host.Api.Sales;
public sealed record IncentiveProgramInput(string Kind,string Name,Guid? CustomerId=null,Guid? UserId=null);
public sealed record IncentivePolicyInput(long Revision,DateOnly From,DateOnly To,JsonElement Config);
public sealed record IncentivePeriodInput(DateOnly From,DateOnly To);
public sealed record IncentiveRunInput(Guid ProgramId,Guid PeriodId,DateOnly ValuationDate,DateOnly PostingDate,string Reason,Guid[]? InvoiceIds=null);
public sealed record IncentiveReviewInput(string Reference);
public sealed record IncentiveEnabledInput([property:JsonRequired]bool Enabled);
public sealed record IncentiveGrantInput(Guid UserId,[property:JsonRequired]bool Active);
public sealed record IncentivePeriodReviewInput([property:JsonRequired]bool Lock,string Reference);
public sealed record IncentiveOffsetInput(Guid PositiveClaimId,Guid NegativeClaimId,decimal Amount,DateOnly PostingDate,string Reference,string Reason);
public sealed record IncentiveSettlementInput(Guid ClaimId,[property:JsonRequired]decimal Net,[property:JsonRequired]decimal Tax,DateOnly PostingDate,string Reference,string Reason,string Evidence,JsonElement Items,Guid? PriorSettlementId=null);
internal static class IncentiveEndpoints
{
 private static async Task<object> Value(CompanySession s,string sql,CancellationToken ct,params DbArg[]args)=>Element((await One(s,sql+"::text AS body",ct,args))["body"]!);
 private static DbArg Id(Guid id)=>new("id",id);
 private static DbArg J(string name,object value)=>new(name,JsonSerializer.Serialize(value,ApiJson.Options),NpgsqlDbType.Jsonb);
 private static async Task<IResult> Write(HttpContext h,CompanySession s,Idempotency idem,string cap,string route,Guid id,object payload,string sql,DbArg[] args,CancellationToken ct,int status=201)
 {await Read(s,"SELECT incentives.require_access(@cap)",ct,new DbArg("cap",cap));var stored=await idem.ExecuteAsync(route,h.Request.Headers["Idempotency-Key"].ToString(),Json(payload),async()=>{var body=await Value(s,sql,ct,args);await Sql.AuditAsync(s,"incentives.changed","incentive",id,h.TraceIdentifier,ct);return ApiJson.Stored(body,status);},ct);return ApiJson.Result(stored);}
 public static void Map(RouteGroupBuilder g)
 {
 g.MapGet("/incentives/programs",async(int? page,int? pageSize,CompanySession s,CancellationToken ct)=>{var(offset,size)=Page(page,pageSize);return Results.Ok(await Value(s,"SELECT incentives.list_programs(@offset,@size)",ct,new DbArg("offset",offset),new DbArg("size",size)));}).WithMetadata(new Permission("incentives.read"));
 g.MapGet("/incentives/programs/{id:guid}",async(Guid id,CompanySession s,CancellationToken ct)=>Results.Ok(await Value(s,"SELECT incentives.program_json(@id)",ct,Id(id)))).WithMetadata(new Permission("incentives.read"));
 g.MapGet("/incentives/ledger",async(int? page,int? pageSize,CompanySession s,CancellationToken ct)=>{var(offset,size)=Page(page,pageSize);return Results.Ok(await Value(s,"SELECT incentives.ledger_page(@offset,@size)",ct,new DbArg("offset",offset),new DbArg("size",size)));}).WithMetadata(new Permission("incentives.read"));
 g.MapGet("/incentives/me",async(HttpContext h,CompanySession s,CancellationToken ct)=>{h.Response.Headers.CacheControl="no-store";return Results.Ok(await Value(s,"SELECT incentives.personal()",ct));}).WithMetadata(new Permission("incentives.self.read"));
 g.MapPost("/incentives/programs",async(IncentiveProgramInput x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{var id=Guid.NewGuid();return await Write(h,s,idem,"incentives.manage","POST /incentives/programs",id,x,"SELECT incentives.create_program(@id,@kind,@name,@customer,@user)",[Id(id),new("kind",x.Kind),new("name",x.Name),new("customer",x.CustomerId,NpgsqlDbType.Uuid),new("user",x.UserId,NpgsqlDbType.Uuid)],ct);}).WithMetadata(new Permission("incentives.manage"));
 g.MapPut("/incentives/programs/{id:guid}/enabled",async(Guid id,IncentiveEnabledInput x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{var v=Version(h);return await Write(h,s,idem,"incentives.manage","PUT /incentives/programs/enabled",id,new{id,v,x},"SELECT incentives.set_program(@id,@v,@enabled)",[Id(id),new("v",v),new("enabled",x.Enabled)],ct,200);}).WithMetadata(new Permission("incentives.manage"));
 g.MapPost("/incentives/programs/{program:guid}/policies",async(Guid program,IncentivePolicyInput x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{Check.That(x.Config.ValueKind==JsonValueKind.Object,"config","Explicit policy object required.");var id=Guid.NewGuid();return await Write(h,s,idem,"incentives.manage","POST /incentives/policies",id,new{program,x},"SELECT incentives.create_policy(@id,@program,@rev,@from,@to,@config)",[Id(id),new("program",program),new("rev",x.Revision),new("from",x.From),new("to",x.To),J("config",x.Config)],ct);}).WithMetadata(new Permission("incentives.manage"));
 g.MapPost("/incentives/policies/{id:guid}/approve",async(Guid id,IncentiveReviewInput x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>await Write(h,s,idem,"incentives.approve","POST /incentives/policies/approve",id,new{id,x},"SELECT incentives.approve_policy(@id,@ref)",[Id(id),new("ref",x.Reference)],ct,200)).WithMetadata(new Permission("incentives.approve"));
 g.MapPost("/incentives/periods",async(IncentivePeriodInput x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{var id=Guid.NewGuid();return await Write(h,s,idem,"incentives.manage","POST /incentives/periods",id,x,"SELECT incentives.create_period(@id,@from,@to)",[Id(id),new("from",x.From),new("to",x.To)],ct);}).WithMetadata(new Permission("incentives.manage"));
 g.MapPost("/incentives/periods/{id:guid}/review",async(Guid id,IncentivePeriodReviewInput x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{var v=Version(h);return await Write(h,s,idem,"incentives.approve","POST /incentives/periods/review",id,new{id,v,x},"SELECT incentives.review_period(@id,@v,@lock,@ref)",[Id(id),new("v",v),new("lock",x.Lock),new("ref",x.Reference)],ct,200);}).WithMetadata(new Permission("incentives.approve"));
 g.MapPost("/incentives/runs",async(IncentiveRunInput x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{var id=Guid.NewGuid();return await Write(h,s,idem,"incentives.manage","POST /incentives/runs",id,x,"SELECT incentives.create_run(@id,@program,@period,@valuation,@posting,@reason,@ids)",[Id(id),new("program",x.ProgramId),new("period",x.PeriodId),new("valuation",x.ValuationDate),new("posting",x.PostingDate),new("reason",x.Reason),new("ids",x.InvoiceIds,NpgsqlDbType.Array|NpgsqlDbType.Uuid)],ct);}).WithMetadata(new Permission("incentives.manage"));
 g.MapGet("/incentives/runs/{id:guid}",async(Guid id,CompanySession s,CancellationToken ct)=>Results.Ok(await Value(s,"SELECT incentives.run_json(@id)",ct,Id(id)))).WithMetadata(new Permission("incentives.read"));
 foreach(var action in new[]{"approve","reject"}){var selected=action;g.MapPost("/incentives/runs/{id:guid}/"+selected,async(Guid id,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{var v=Version(h);return await Write(h,s,idem,selected=="approve"?"incentives.approve":"incentives.manage","POST /incentives/runs/"+selected,id,new{id,v},"SELECT incentives."+selected+"_run(@id,@v)",[Id(id),new("v",v)],ct,200);}).WithMetadata(new Permission(selected=="approve"?"incentives.approve":"incentives.manage"));}
 g.MapPost("/incentives/settlements",async(IncentiveSettlementInput x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{Check.That(x.Items.ValueKind==JsonValueKind.Array,"items","Explicit settlement items array required.");await Read(s,"SELECT incentives.require_settlement(@claim)",ct,new DbArg("claim",x.ClaimId));var id=Guid.NewGuid();return await Write(h,s,idem,"incentives.settle","POST /incentives/settlements",id,x,"SELECT incentives.settle(@id,@claim,@net,@tax,@date,@ref,@reason,@evidence,@items,@prior)",[Id(id),new("claim",x.ClaimId),new("net",x.Net),new("tax",x.Tax),new("date",x.PostingDate),new("ref",x.Reference),new("reason",x.Reason),new("evidence",x.Evidence),J("items",x.Items),new("prior",x.PriorSettlementId,NpgsqlDbType.Uuid)],ct);}).WithMetadata(new Permission("incentives.settle"));
 g.MapPost("/incentives/offsets",async(IncentiveOffsetInput x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{var id=Guid.NewGuid();return await Write(h,s,idem,"incentives.settle","POST /incentives/offsets",id,x,"SELECT incentives.offset_claims(@id,@positive,@negative,@amount,@date,@ref,@reason)",[Id(id),new("positive",x.PositiveClaimId),new("negative",x.NegativeClaimId),new("amount",x.Amount),new("date",x.PostingDate),new("ref",x.Reference),new("reason",x.Reason)],ct);}).WithMetadata(new Permission("incentives.settle"));
 g.MapPut("/incentives/programs/{id:guid}/display-grants",async(Guid id,IncentiveGrantInput x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{if(!long.TryParse(h.Request.Headers["If-Match"].ToString().Trim('"'),out var v)||v<0)throw new BusinessException("version_required","Supply If-Match with 0 for a new grant or its current version.",428);return await Write(h,s,idem,"incentives.grants.manage","PUT /incentives/display-grants",id,new{id,v,x},"SELECT incentives.grant_display(@id,@user,@active,@v)",[Id(id),new("user",x.UserId),new("active",x.Active),new("v",v)],ct,200);}).WithMetadata(new Permission("incentives.grants.manage"));
 }
}
